import{c as a,Q as t,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"GetSortMaxMinTmpSize","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetSortMaxMinTmpSize","slug":"getsortmaxmintmpsize"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/排序操作/GetSortMaxMinTmpSize.md","filePath":"api/SIMD-API/高阶API/排序操作/GetSortMaxMinTmpSize.md"}'),p={name:"api/SIMD-API/高阶API/排序操作/GetSortMaxMinTmpSize.md"};function l(i,e,o,r,d,c){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="getsortmaxmintmpsize" tabindex="-1">GetSortMaxMinTmpSize <a class="header-anchor" href="#getsortmaxmintmpsize" aria-label="Permalink to &quot;GetSortMaxMinTmpSize&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>带SortConfig模板参数的kernel侧Sort接口的计算需要开发者预留/申请临时空间，本接口用于在host侧获取预留/申请的最大最小临时空间大小，开发者基于此范围选择合适的空间大小作为Tiling参数传递到kernel侧使用。</p><ul><li>为保证功能正确，预留/申请的临时空间大小不能小于最小临时空间大小；</li><li>在最小临时空间-最大临时空间范围内，随着临时空间增大，kernel侧接口计算性能会有一定程度的优化提升。为了达到更好的性能，开发者可以根据实际的内存使用情况进行空间预留/申请。</li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetSortMaxMinTmpSize(const ge::Shape &amp;srcShape, ge::DataType valueType, ge::DataType indexType, bool isReuseSource, const SortConfig &amp;config, uint32_t &amp;maxValue, uint32_t &amp;minValue)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 接口参数列表</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>srcShape</td><td>输入</td><td>输入的shape信息。</td></tr><tr><td>valueType</td><td>输入</td><td>输入、输出Value的数据类型。与Sort接口的模板参数T保持一致。</td></tr><tr><td>indexType</td><td>输入</td><td>输入、输出Index的数据类型。与Sort接口的模板参数U保持一致。</td></tr><tr><td>isReuseSource</td><td>输入</td><td>是否复用源操作数输入的空间。与Sort接口的参数isReuseSource保持一致。</td></tr><tr><td>config</td><td>输入</td><td>Sort的相应配置：选择的排序算法，排序结果的升降序，输入输出是否带有索引数据。数据类型SortConfig，定义如下。其中的参数hasSrcIndex、hasDstIndex与使用的Sort接口是否带有输入索引、输出索引的情况保持一致；当前hasSrcIndex = true, hasDstIndex = false组合不支持。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1083884503520&quot;&gt;struct SortConfig { SortType type = SortType::RADIX_SORT; // 排序算法 bool isDescend = false; // 是否降序排序，默认值为false，输出结果升序排序 bool hasSrcIndex = false; // 是否带有输入索引 bool hasDstIndex = false; // 是否带有输出索引 };&lt;/pre&gt; 其中，排序算法的数据类型SortType取值如下。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1623155513359&quot;&gt;enum class SortType { RADIX_SORT, // 使用基排序算法实现 MERGE_SORT // 使用归并排序实现 };&lt;/pre&gt;</td></tr><tr><td>maxValue</td><td>输出</td><td>Sort接口能完成计算所需的最大临时空间大小，超出该值的空间不会被该接口使用。在最小临时空间-最大临时空间范围内，随着临时空间增大，kernel侧接口计算性能会有一定程度的优化提升。为了达到更好的性能，开发者可以根据实际的内存使用情况进行空间预留/申请。最大空间大小为0表示计算不需要临时空间。 说明： maxValue仅作为参考值，有可能大于Unified Buffer剩余空间的大小，该场景下，开发者需要根据Unified Buffer剩余空间的大小来选取合适的临时空间大小。</td></tr><tr><td>minValue</td><td>输出</td><td>Sort接口能完成计算所需最小临时空间大小。为保证功能正确，接口计算时预留/申请的临时空间不能小于该数值。最小空间大小为0表示计算不需要临时空间。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的调用样例请参考<a href="./../数学计算/更多样例-83.html">更多样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 输入shape信息为1024;算子输入的数据类型为uint32_t;不允许修改源操作数</span></span>
<span class="line"><span>std::vector&lt;int64_t&gt; shape_vec = {1024};</span></span>
<span class="line"><span>ge::Shape srcShape(shape_vec);</span></span>
<span class="line"><span>ge::DataType valueType = ge::DT_UINT32;</span></span>
<span class="line"><span>ge::DataType indexType = ge::DT_UINT32;</span></span>
<span class="line"><span>bool isDescend = true;</span></span>
<span class="line"><span>bool hasSrcIndex = false;</span></span>
<span class="line"><span>bool hasDstIndex = false;</span></span>
<span class="line"><span>bool isReuseSource = false;</span></span>
<span class="line"><span>AscendC::SortConfig config;</span></span>
<span class="line"><span>config.type = AscendC::SortType::RADIX_SORT;</span></span>
<span class="line"><span>config.isDescend = isDescend;</span></span>
<span class="line"><span>config.hasSrcIndex = hasSrcIndex;</span></span>
<span class="line"><span>config.hasDstIndex = hasDstIndex;</span></span>
<span class="line"><span>uint32_t maxValue = 0;</span></span>
<span class="line"><span>uint32_t minValue = 0;</span></span>
<span class="line"><span>AscendC::GetSortMaxMinTmpSize(srcShape, valueType, indexType, isReuseSource, config, maxValue, minValue);</span></span></code></pre></div>`,16)])])}const S=a(p,[["render",l]]);export{h as __pageData,S as default};
